/// <summary>
///     extension of class <c>AVAPCMEmailFormatter</c>
/// </summary>
[ExtensionOf(classStr(AVAPCMEmailFormatter))]
final class AVAAVAPCMEmailFormatterCls_Extension
{
    public SalesTable   clsSalesTable;
    public SalesTable   clsSalesTable2Check;
    public CustTable    clsCustTable;
    public CustTable    clsCustTable2Check;

    public boolean      clsFillVariablesInitialized;

}

Method.Source:
/// <summary>
///     AVA <c>setContract</c> method.
///     Set the record id and table id based on the contract
///     AVA - Schneider 28.03.2024
/// </summary>
/// <param name="_rdpContract">
///     <c>Object</c> as type
/// </param>
protected void setContract(Object _rdpContract)
{
    CustConfirmJour locCustConfirmJour;

    next setContract(_rdpContract);

    switch (true)
    {
        //existing report contracts extension
        case _rdpContract is SalesConfirmContract:
            if (refRecId)
            {
                locCustConfirmJour  = CustConfirmJour::findRecId(refRecId);
                clsSalesTable       = locCustConfirmJour.salesTable();
                clsCustTable        = CustTable::find(locCustConfirmJour.OrderAccount);
            }
            break;

        //new report contracts extension
        case _rdpContract is AVASalesOrderDelegationReportContract:
            AVASalesOrderDelegationReportContract locAVASalesOrderDelegationReportContract = _rdpContract as AVASalesOrderDelegationReportContract;
            refTableId  = tableNum(SalesTable);
            refRecId    = locAVASalesOrderDelegationReportContract.parmRecordId();
            if (refRecId)
            {
                clsCustTable        = SalesTable::findRecId(refRecId).custTable_CustAccount();
            }
            break;


    }

}

