/// <summary>
///     AVA <c>construct</c> method.
///     Constructor for <c>AVAPCMEmailFormatter</c> class
///     AVA - Schneider 28.03.2024
/// </summary>
/// <param name="_reportDataContract">
///     <c>SrsReportDataContract</c> as type
/// </param>
/// <returns>
///     <c>AVAPCMEmailFormatter</c> as return value
/// </returns>
public static AVAPCMEmailFormatter construct(SrsReportDataContract _reportDataContract)
{
    AVAPCMEmailFormatter                    loAVAPCMEmailFormatter;
    AVASalesOrderDelegationReportContract   locAVASalesOrderDelegationReportContract;

    loAVAPCMEmailFormatter = next construct(_reportDataContract);

    switch (true)
    {
        case _reportDataContract.parmRdpContract() is AVASalesOrderDelegationReportContract:
            locAVASalesOrderDelegationReportContract = _reportDataContract.parmRdpContract() as AVASalesOrderDelegationReportContract;
            loAVAPCMEmailFormatter.parmRefTableId(tableNum(SalesTable));
            loAVAPCMEmailFormatter.parmRefRecId(_reportDataContract.parmRdpContract().parmRecordId());
            break;
    }

    if (loAVAPCMEmailFormatter.parmRefRecId())
    {
        loAVAPCMEmailFormatter.parmHasRdpContract(true);
    }

    return loAVAPCMEmailFormatter;
}

