 /// <summary>
 ///     AVA <c>fillVariables</c> method.
 ///     AVA - Schneider 28.03.2024
 /// </summary>
 /// <param name="_inputString">
 ///     <c>str</c> as type
 /// </param>
 /// <param name="_languageId">
 ///     <c>LanguageId</c> as type
 /// </param>
 /// <returns>
 ///     <c>str</c> as return value
 /// </returns>
 public str fillVariables(str _inputString, LanguageId _languageId)
 {
     str                         retVal;

     RefTableId                  locRefTableId;
     RefRecId                    locRefRecId;
     Common                      locCommon;
     SalesTable                  locSalesTable;
     CustTable                   locCustTable;

     if(!clsFillVariablesInitialized)
     {
         this.avaSetTables2Check();
     }

     retVal = next fillVariables(_inputString, _languageId);

     // keep original
     locRefTableId           = this.parmRefTableId();
     locRefRecId             = this.parmRefRecId();

     // SalesTable values
     locSalesTable   = this.parmClsSalesTable2Check();
     locCommon       = locSalesTable;
     if(locCommon.RecId)
     {
         this.parmClsSalesTable2Check(null);
         this.parmRefTableId(locCommon.TableId);
         this.parmRefRecId(locCommon.RecId);
         this.setCommon();
         //Replace variables based on additional table
         retVal = this.fillVariables(retVal, _languageId);
     }

     // CustTable values
     locCustTable    = this.parmClsCustTable2Check();
     locCommon       = locCustTable;
     if(locCommon.RecId)
     {
         this.parmClsCustTable2Check(null);
         this.parmRefTableId(locCommon.TableId);
         this.parmRefRecId(locCommon.RecId);
         this.setCommon();
         //Replace variables based on additional table
         retVal = this.fillVariables(retVal, _languageId);
     }

     // back to orig
     this.parmRefTableId(locRefTableId);
     this.parmRefRecId(locRefRecId);
     this.setCommon();
     clsFillVariablesInitialized = false;

     return retVal;
}

/// <summary>
///     AVA <c>avaSetTables2Check</c> method.
///     AVA - Schneider 28.03.2024
/// </summary>
public void avaSetTables2Check()
{
    clsSalesTable2Check = this.parmClsSalesTable();
    clsCustTable2Check  = this.parmClsCustTable();

    clsFillVariablesInitialized = true;
}
